package com.example.spring_blog.user;import com.example.spring_blog.error.UnAuthorizedException;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.stereotype.Service;import org.springframework.web.client.HttpClientErrorException;import org.springframework.web.client.ResourceAccessException;@Service@Slf4j@RequiredArgsConstructorpublic class GoogleLoginService {    private final GoogleApiClient googleApiClient;    private final UserService userService;    public String getAuthorizeUrl() {        return googleApiClient.getAuthorizeUrl();    }    public SessionUserDTO login(String code) {        if (code == null) {            throw new UnAuthorizedException("구글 로그인이 취소되었습니다.");        }        try{            UserResponse.GoogleOauthToken token = googleApiClient.requestAccessToken(code);            UserResponse.GoogleUserInfo googleUserInfo = googleApiClient.requestProfile(token.getAccessToken());            return userService.googleLogin(googleUserInfo);        }catch (HttpClientErrorException e){            log.warn("구글 API 오류 : {}" + e.getResponseBodyAsString());            throw new UnAuthorizedException("구글 로그인에 실패했습니다.");        }catch (ResourceAccessException e) {            log.warn("구글 서버연결 실패 : {}", e.getMessage());            throw new UnAuthorizedException("구글 서버에 연결할 수 없습니다.");        }    }}